def transform(g):
    bg=max(set(v for r in g for v in r), key=lambda v: sum(r.count(v) for r in g))  # most common = bg
    shape=next(v for v in {v for r in g for v in r} if v!=bg)
    cells=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v==shape]
    r0,r1=min(i for i,_ in cells),max(i for i,_ in cells)
    c0,c1=min(j for _,j in cells),max(j for _,j in cells)
    out=[row[:] for row in g]
    FILL=2
    # 1) complete bbox rectangle outline
    for j in range(c0,c1+1):
        for i in (r0,r1):
            if out[i][j]==bg: out[i][j]=FILL
    for i in range(r0,r1+1):
        for j in (c0,c1):
            if out[i][j]==bg: out[i][j]=FILL
    # 2) interior straight segments (len>=2) of shape color extend along orientation to the frame
    H=set(); V=set()
    for i in range(r0,r1+1):
        for j in range(c0,c1+1):
            if g[i][j]==shape and g[i][j+1]==shape: H.add((i,j))
            if g[i][j]==shape and g[i+1][j]==shape: V.add((i,j))
    # grow segments
    segs=[]
    for (i,j) in H:
        if (i,j-1) not in H:  # start
            k=j
            while (i,k) in H: k+=1
            segs.append(('H',i,j,k-1))
    for (i,j) in V:
        if (i-1,j) not in V:
            k=i
            while (k,j) in V: k+=1
            segs.append(('V',j,i,k-1))
    for o,a,b,e in segs:
        interior = (o=='H' and c0<b and c1>a) or (o=='V' and r0<b and r1>a)
        if not interior: continue
        if o=='H':
            for j in range(c0,c1+1):
                if out[a][j]==bg: out[a][j]=FILL
        else:
            for i in range(r0,r1+1):
                if out[i][a]==bg: out[i][a]=FILL
    return out
