    """The (r0, r1, c0, c1) bounds of all cells of the given color."""
    cells = [(i, j) for i, r in enumerate(grid) for j, v in enumerate(r) if v == color]
    return min(i for i, _ in cells), max(i for i, _ in cells), min(j for _, j in cells), max(j for _, j in cells)

def complete_frame(grid, fill=2):
    """Complete the bounding-box rectangle outline of the non-background shape with fill, and extend interior straight shape lines along their orientation to the frame."""
    bg = max({v for row in grid for v in row}, key=lambda v: sum(r.count(v) for r in grid))
